import os

from pyearthtools.data.archive import (
    register_archive,
    load_root_directories_from_config,
)


# ---------------------------------------------------------------------------                                                                                      
# Default S3 root directory mapping.                                                                                                                               
# These defaults point at the public Met Office ASDI buckets.                                                                                                      
# Override in ~/.pyearthtoolsconfig under [aws].                                                                                                                   
# ---------------------------------------------------------------------------                                                                                      

ROOT_DIRECTORIES = {
    "MOGlobal10km": "s3://met-office-atmospheric-model-data/global-deterministic/",
    "MOUKV_AWS":    "s3://met-office-atmospheric-model-data/uk-deterministic/",
}

register_archive("ROOT_DIRECTORIES")(ROOT_DIRECTORIES)

# Make 'aws' a registered archive namespace so pyearthtools can find it                                                                                            
import site_archive_aws  # noqa: E402                                                                                                                              

from site_archive_aws.mo_global_10km import MOGlobal10km  # noqa: E402, F401                                                                                       
from site_archive_aws.mo_ukv import MOUKV  # noqa: E402, F401


register_archive("aws")(site_archive_aws)

# Load user-specific overrides from the PyEarthTools config file                                                                                                   
config_path = os.path.expanduser("~/.pyearthtoolsconfig")
load_root_directories_from_config(config_path=config_path)

try:
    # Generated by setuptools-scm at install time; not in version control.                                                                                         
    from ._version import __version__  # type: ignore                                                                                                              
except ImportError:
    __version__ = "999"

__all__ = [
    "MOGlobal10km",
    "MOUKV",
]

